import React, { createContext, useContext, useState, useEffect } from 'react';
import { getData, saveData } from '../services/localStorageService';
import { generateId } from '../utils/helpers';

const AuthContext = createContext();

const DEFAULT_ADMIN = {
  id: 'admin',
  name: 'Admin User',
  email: 'admin@tripnova.com',
  password: 'admin123',
  role: 'admin',
  phone: '+91 9876543210',
  createdAt: new Date().toISOString()
};

export const AuthProvider = ({ children }) => {
  const [currentUser, setCurrentUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Initialize admin on first launch
    const users = getData('users');
    if (!users.find(u => u.email === 'admin@tripnova.com')) {
      saveData('users', [...users, DEFAULT_ADMIN]);
    }
    // Restore session
    const saved = localStorage.getItem('currentUser');
    if (saved) setCurrentUser(JSON.parse(saved));
    setLoading(false);
  }, []);

  const login = (email, password) => {
    const users = getData('users');
    const user = users.find(u => u.email === email && u.password === password);
    if (user) {
      const { password: _, ...safeUser } = user;
      setCurrentUser(safeUser);
      localStorage.setItem('currentUser', JSON.stringify(safeUser));
      return { success: true, user: safeUser };
    }
    return { success: false, message: 'Invalid email or password.' };
  };

  const signup = (name, email, password, phone) => {
    const users = getData('users');
    if (users.find(u => u.email === email)) {
      return { success: false, message: 'Email already registered.' };
    }
    const newUser = {
      id: generateId(), name, email, password, phone,
      role: 'user', createdAt: new Date().toISOString()
    };
    saveData('users', [...users, newUser]);
    const { password: _, ...safeUser } = newUser;
    setCurrentUser(safeUser);
    localStorage.setItem('currentUser', JSON.stringify(safeUser));
    return { success: true, user: safeUser };
  };

  const logout = () => {
    setCurrentUser(null);
    localStorage.removeItem('currentUser');
  };

  const updateProfile = (updates) => {
    const users = getData('users');
    const idx = users.findIndex(u => u.id === currentUser.id);
    if (idx !== -1) {
      users[idx] = { ...users[idx], ...updates };
      saveData('users', users);
      const { password: _, ...safeUser } = users[idx];
      setCurrentUser(safeUser);
      localStorage.setItem('currentUser', JSON.stringify(safeUser));
      return true;
    }
    return false;
  };

  const resetPassword = (email, newPassword) => {
    const users = getData('users');
    const idx = users.findIndex(u => u.email === email);
    if (idx !== -1) {
      users[idx].password = newPassword;
      saveData('users', users);
      return { success: true };
    }
    return { success: false, message: 'Email not found.' };
  };

  return (
    <AuthContext.Provider value={{ currentUser, loading, login, signup, logout, updateProfile, resetPassword }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);
export default AuthContext;
